INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3631113, 508746, 30049, '<td valign="top">OMG.  You really took a photo at someones funeral?!  Wow.</td>', 'OMG.  You really took a photo at someones funeral?!  Wow.', '2007-05-09 01:10:36.000000', NULL, 1),
(3631119, 509521, 63119, '<td valign="top">Love the processing you have done here.  Hope you have it in your comments how you did it. Great focus and composition.  Love the desaturated background.  Make he girl stand out even more.</td>', 'Love the processing you have done here.  Hope you have it in your comments how you did it. Great focus and composition.  Love the desaturated background.  Make he girl stand out even more.', '2007-05-09 01:10:58.000000', NULL, 1),
(3631206, 506251, 36371, '<td valign="top">Cannot add any text to the photo. Sorry....</td>', 'Cannot add any text to the photo. Sorry....', '2007-05-09 01:32:43.000000', NULL, 1),
(3631232, 509443, 36371, '<td valign="top">Watch your backgrounds. This looks like any street in America and the ladies certainly don''t look Caribbean. Wish you had shown more of the photo to depict something that looks Caribbean other than the steel drum.</td>', 'Watch your backgrounds. This looks like any street in America and the ladies certainly don''t look Caribbean. Wish you had shown more of the photo to depict something that looks Caribbean other than the steel drum.', '2007-05-09 01:35:14.000000', NULL, 1),
(3631277, 509230, 27339, '<td valign="top">I think you need a stronger inclusion of humans to present this image as a Festival. The repetition of the flowers and their patterns are the strong visual elements of this photo.</td>', 'I think you need a stronger inclusion of humans to present this image as a Festival. The repetition of the flowers and their patterns are the strong visual elements of this photo.', '2007-05-09 01:42:47.000000', NULL, 1),
(3631352, 506751, 27339, '<td valign="top">this is a good photograph, but it is being hurt by the poor quality of the image itself</td>', 'this is a good photograph, but it is being hurt by the poor quality of the image itself', '2007-05-09 02:02:17.000000', NULL, 1),
(3631356, 509122, 27339, '<td valign="top">what kind of cultural trance is this? show us</td>', 'what kind of cultural trance is this? show us', '2007-05-09 02:04:12.000000', NULL, 1),
(3631360, 508286, 27339, '<td valign="top">looks unhealthy haha</td>', 'looks unhealthy haha', '2007-05-09 02:04:39.000000', NULL, 1),
(3631376, 507306, 27339, '<td valign="top">Is the image softly focused or sharpened a lot? The people in the lower background are visually distracting</td>', 'Is the image softly focused or sharpened a lot? The people in the lower background are visually distracting', '2007-05-09 02:08:06.000000', NULL, 1),
(3631386, 506670, 27339, '<td valign="top">this is a nice architectural image</td>', 'this is a nice architectural image', '2007-05-09 02:09:50.000000', NULL, 1),
(3631393, 507555, 27339, '<td valign="top">Image is overly contrasted and over saturated. The highlights are all blown out making the image unpleasing to the eye and leaving little area for the eye to rest. The subjects themselves are interesting.</td>', 'Image is overly contrasted and over saturated. The highlights are all blown out making the image unpleasing to the eye and leaving little area for the eye to rest. The subjects themselves are interesting.', '2007-05-09 02:12:03.000000', NULL, 1),
(3631399, 507912, 27339, '<td valign="top">If this involved a service or a church I could see it being directly related to a cultural event</td>', 'If this involved a service or a church I could see it being directly related to a cultural event', '2007-05-09 02:13:14.000000', NULL, 1),
(3631405, 509053, 27339, '<td valign="top">tone down the color saturation and I think this image is good to go</td>', 'tone down the color saturation and I think this image is good to go', '2007-05-09 02:15:00.000000', NULL, 1),
(3631411, 509199, 27339, '<td valign="top">I think some of the foliage in the foreground distracts from the horse drawn carriage. Colors are lovely though</td>', 'I think some of the foliage in the foreground distracts from the horse drawn carriage. Colors are lovely though', '2007-05-09 02:16:41.000000', NULL, 1),
(3631432, 509187, 50641, '<td valign="top">sing it, girls</td>', 'sing it, girls', '2007-05-09 02:23:13.000000', NULL, 1),
(3631439, 508048, 47487, '<td valign="top">I like the expression you captured. Looks like he''s wondering if anyone will show up.</td>', 'I like the expression you captured. Looks like he''s wondering if anyone will show up.', '2007-05-09 02:25:42.000000', NULL, 1),
(3631440, 509236, 47487, '<td valign="top">nice colors, but it seems out of focus.</td>', 'nice colors, but it seems out of focus.', '2007-05-09 02:26:15.000000', NULL, 1),
(3631443, 506751, 47487, '<td valign="top">nice dreamy feel to it.</td>', 'nice dreamy feel to it.', '2007-05-09 02:26:43.000000', NULL, 1),
(3631454, 509120, 47487, '<td valign="top">wrong challenge?</td>', 'wrong challenge?', '2007-05-09 02:30:30.000000', NULL, 1),
(3631456, 509281, 47487, '<td valign="top">I wish the focus was on the other boat, and not on the ''tails'' of the one you were on and the one next to it.</td>', 'I wish the focus was on the other boat, and not on the ''tails'' of the one you were on and the one next to it.', '2007-05-09 02:31:01.000000', NULL, 1),
(3631463, 507306, 47487, '<td valign="top">There''s something strange going on with the blur in parts of this image; I can''t figure it out. Otherwise, a nice composition of an interesting subject.</td>', 'There''s something strange going on with the blur in parts of this image; I can''t figure it out. Otherwise, a nice composition of an interesting subject.', '2007-05-09 02:34:44.000000', NULL, 1),
(3631464, 509423, 60505, '<td valign="top">IMHO would have been improved by faster exposure to freeze the action and bring out the detail of the gold stitching.</td>', 'IMHO would have been improved by faster exposure to freeze the action and bring out the detail of the gold stitching.', '2007-05-09 02:34:54.000000', NULL, 1),
(3631466, 509122, 47487, '<td valign="top">-blurry<br/>-color balance off<br/>-doesn''t really have much to do with the challenge without the title.<br/> <br/>Don''t be discouraged, though -- keep trying!</td>', '-blurry-color balance off-doesn''t really have much to do with the challenge without the title. Don''t be discouraged, though -- keep trying!', '2007-05-09 02:36:06.000000', NULL, 1),
(3631467, 507555, 60505, '<td valign="top">I think the background is too burned out and therefore the costumes too isolated from their environment</td>', 'I think the background is too burned out and therefore the costumes too isolated from their environment', '2007-05-09 02:36:32.000000', NULL, 1),
(3631470, 509335, 47487, '<td valign="top">Nice idea, but the grain seems excessive, even for what I think you may have been trying to accomplish.</td>', 'Nice idea, but the grain seems excessive, even for what I think you may have been trying to accomplish.', '2007-05-09 02:37:15.000000', NULL, 1),
(3631473, 508286, 47487, '<td valign="top">um. why? Not a compelling subject, no real connection to challenge. And while I don''t care overmuch, people are going to ding you a lot because it''s small.</td>', 'um. why? Not a compelling subject, no real connection to challenge. And while I don''t care overmuch, people are going to ding you a lot because it''s small.', '2007-05-09 02:38:00.000000', NULL, 1),
(3631476, 509330, 60505, '<td valign="top">would like it sharper, but v nice composition</td>', 'would like it sharper, but v nice composition', '2007-05-09 02:38:19.000000', NULL, 1),
(3631481, 508637, 60505, '<td valign="top">nice Bokeh and good composition and colors</td>', 'nice Bokeh and good composition and colors', '2007-05-09 02:39:06.000000', NULL, 1),
(3631486, 507645, 47487, '<td valign="top">cute child, but the eyes are out of focus. In a portrait or candid it''s always a good idea, unless you''re going for a specific and contrary effect, to make sure the eyes are sharply in focus. (very cute face painting! :)</td>', 'cute child, but the eyes are out of focus. In a portrait or candid it''s always a good idea, unless you''re going for a specific and contrary effect, to make sure the eyes are sharply in focus. (very cute face painting! :)', '2007-05-09 02:40:50.000000', NULL, 1),
(3631489, 506246, 60505, '<td valign="top">needs a little more contrast.Foreground subjects do not appear to interesting. Background is fascinating! may have been better not to have shot directly into the light</td>', 'needs a little more contrast.Foreground subjects do not appear to interesting. Background is fascinating! may have been better not to have shot directly into the light', '2007-05-09 02:41:30.000000', NULL, 1),
(3631494, 508746, 60505, '<td valign="top">Clean, solemn, dignified symmetrical composition</td>', 'Clean, solemn, dignified symmetrical composition', '2007-05-09 02:42:33.000000', NULL, 1),
(3631501, 507306, 60505, '<td valign="top">would have been nicer if photo was sharper. Great lighting and composition</td>', 'would have been nicer if photo was sharper. Great lighting and composition', '2007-05-09 02:43:58.000000', NULL, 1),
(3631526, 506636, 67258, '<td valign="top">This looks as though it may be an interesting photo, but is too small to make a judgement.  I suspect you are a new member - if so, have a read of <a href="//www.dpchallenge.com/tutorial.php?TUTORIAL_ID=26" rel="nofollow" target="_blank">this</a> tutorial showing how to prepare your entry for DPC.  If you need any more help, feel free to PM me.</td>', 'This looks as though it may be an interesting photo, but is too small to make a judgement.  I suspect you are a new member - if so, have a read of this tutorial showing how to prepare your entry for DPC.  If you need any more help, feel free to PM me.', '2007-05-09 02:51:33.000000', NULL, 1),
(3631535, 507466, 75713, '<td valign="top">I like the blue in the shadows</td>', 'I like the blue in the shadows', '2007-05-09 02:55:50.000000', NULL, 1),
(3631551, 506636, 66353, '<td valign="top">Why so small? It''s impossible to see anything this way...</td>', 'Why so small? It''s impossible to see anything this way...', '2007-05-09 03:06:43.000000', NULL, 1),
(3631564, 506636, 41574, '<td valign="top">Way too small for me to have a strong opinion about. As it is, it might be nice, but it doesn''t feel like anything but a so-so snapshot for the photo-album.</td>', 'Way too small for me to have a strong opinion about. As it is, it might be nice, but it doesn''t feel like anything but a so-so snapshot for the photo-album.', '2007-05-09 03:13:56.000000', NULL, 1),
(3631565, 506246, 41574, '<td valign="top">Nice repetition with the elephants, but they''re not even the focus of the shot. Washed out colors, unpleasantly low contrast, thoughtless composition  sorry, but, in my opinion, this image just doesn''t cut it.</td>', 'Nice repetition with the elephants, but they''re not even the focus of the shot. Washed out colors, unpleasantly low contrast, thoughtless composition  sorry, but, in my opinion, this image just doesn''t cut it.', '2007-05-09 03:15:24.000000', NULL, 1),
(3631566, 508364, 41574, '<td valign="top">I wish the shot were slightly brighter, but, even as it is, I think it''s awesome. Nice clarity, great composition, brilliant choice of subject.<br/> <br/>*You miss the "10" because of the somewhat low brightness, and because I don''t think this really fits the challenge. For the latter reason, I''d give your submission a much lower rating, but I just really like this photograph.</td>', 'I wish the shot were slightly brighter, but, even as it is, I think it''s awesome. Nice clarity, great composition, brilliant choice of subject. *You miss the "10" because of the somewhat low brightness, and because I don''t think this really fits the challenge. For the latter reason, I''d give your submission a much lower rating, but I just really like this photograph.', '2007-05-09 03:16:48.000000', NULL, 1),
(3631569, 509486, 41574, '<td valign="top">Great shot with stunning clarity. I love it.</td>', 'Great shot with stunning clarity. I love it.', '2007-05-09 03:18:05.000000', NULL, 1),
(3631571, 508746, 41574, '<td valign="top">Nice capture, if a bit bland for my taste.</td>', 'Nice capture, if a bit bland for my taste.', '2007-05-09 03:18:38.000000', NULL, 1),
(3631572, 509122, 41574, '<td valign="top">A little too "camera-phone" for my liking.</td>', 'A little too "camera-phone" for my liking.', '2007-05-09 03:19:34.000000', NULL, 1),
(3631575, 508284, 41574, '<td valign="top">Not bad, but I wish the statuette were positioned differently in the frame. Also, I want to see more of the hand that''s pouring the milk.</td>', 'Not bad, but I wish the statuette were positioned differently in the frame. Also, I want to see more of the hand that''s pouring the milk.', '2007-05-09 03:20:41.000000', NULL, 1),
(3631577, 509369, 41574, '<td valign="top">Freakin'' awesome; I love it -- it achieves my first "10" yet.</td>', 'Freakin'' awesome; I love it -- it achieves my first "10" yet.', '2007-05-09 03:22:08.000000', NULL, 1),
(3631581, 508286, 41574, '<td valign="top">This looks like a heavily-cropped, low-resolution snap-shot of a kiosk. I don''t find that it meets the guidelines of the challenge, and, aesthetically, it offers me nothing. Sorry, but that''s my perception.</td>', 'This looks like a heavily-cropped, low-resolution snap-shot of a kiosk. I don''t find that it meets the guidelines of the challenge, and, aesthetically, it offers me nothing. Sorry, but that''s my perception.', '2007-05-09 03:25:56.000000', NULL, 1),
(3631586, 509485, 41574, '<td valign="top">To be honest, my only real complaint about this shot is that it looks "a little <i>too</i> good"; by this I mean, of course, that it lacks realism and spontaneity. The thing looks too set-up, staged, false. Yes, "technically," things look fine: good colors, nice composition, interesting subject. Also, the shot meets the challenge. So, I naturally wouldn''t give this submission a "low grade," but its very "presentational" texture keeps me from being too kind, as well.</td>', 'To be honest, my only real complaint about this shot is that it looks "a little too good"; by this I mean, of course, that it lacks realism and spontaneity. The thing looks too set-up, staged, false. Yes, "technically," things look fine: good colors, nice composition, interesting subject. Also, the shot meets the challenge. So, I naturally wouldn''t give this submission a "low grade," but its very "presentational" texture keeps me from being too kind, as well.', '2007-05-09 03:28:51.000000', NULL, 1),
(3631591, 509053, 41574, '<td valign="top">I wish the human subject weren''t so readily lost in the noise of this shot, but, then, I think that noise is exactly what the image is all about. Overall, I rather like this photograph.</td>', 'I wish the human subject weren''t so readily lost in the noise of this shot, but, then, I think that noise is exactly what the image is all about. Overall, I rather like this photograph.', '2007-05-09 03:31:24.000000', NULL, 1),
(3631593, 509521, 41574, '<td valign="top">Beautiful, mesmerizing photograph.</td>', 'Beautiful, mesmerizing photograph.', '2007-05-09 03:33:04.000000', NULL, 1),
(3631603, 509230, 42181, '<td valign="top">Great shot with the carpet of flowers but IMO the building is distracting</td>', 'Great shot with the carpet of flowers but IMO the building is distracting', '2007-05-09 03:44:12.000000', NULL, 1),
(3631606, 506246, 42181, '<td valign="top">Shame it was taken into the sun, you''ve lost a lot of the colours. Otherwise, good picture of a real cultural event.</td>', 'Shame it was taken into the sun, you''ve lost a lot of the colours. Otherwise, good picture of a real cultural event.', '2007-05-09 03:46:08.000000', NULL, 1),
