(3633808, 509521, 77968, '<td valign="top">WoW! this is an exquisite capture, beautiful light, beautiful saturation of color, fine details. very nicely done</td>', 'WoW! this is an exquisite capture, beautiful light, beautiful saturation of color, fine details. very nicely done', '2007-05-09 15:25:23.000000', NULL, 1),
(3633819, 507976, 77968, '<td valign="top">unfortunately your lighting of the prime subjects on stage did not work well in this shot, I''ve found that an electronic fill flash (a really really long one!) helps me get these kinds of difficult shots, it is however well focused</td>', 'unfortunately your lighting of the prime subjects on stage did not work well in this shot, I''ve found that an electronic fill flash (a really really long one!) helps me get these kinds of difficult shots, it is however well focused', '2007-05-09 15:28:07.000000', NULL, 1),
