INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3641864, 509369, 11854, '<td valign="top">Love the fisheye view! Stunning colors, surreal feel. 10</td>', 'Love the fisheye view! Stunning colors, surreal feel. 10', '2007-05-12 12:04:44.000000', NULL, 1),
(3641867, 509521, 11854, '<td valign="top">Beautiful colors, wonderful detail! 10</td>', 'Beautiful colors, wonderful detail! 10', '2007-05-12 12:06:06.000000', NULL, 1),
(3641902, 509329, 67301, '<td valign="top">Nice shot and composition. Good use of B&amp;W to enphasise age. Negatives for me is the DOF I feel it is neither one or the other as it is it is distracting. IMO the background should have less focus. The crop to the top of the shot is too low and it makes the shot feel unbalanced. = 7</td>', 'Nice shot and composition. Good use of B&W to enphasise age. Negatives for me is the DOF I feel it is neither one or the other as it is it is distracting. IMO the background should have less focus. The crop to the top of the shot is too low and it makes the shot feel unbalanced. = 7', '2007-05-12 12:30:53.000000', NULL, 1),
(3641912, 509068, 67301, '<td valign="top">Fantastic image with great composition and DOF is just right for this image. Good use of B&amp;W too. The distraction is what appears to be a shadow across the bottom of the shot which is a real shame. = 8</td>', 'Fantastic image with great composition and DOF is just right for this image. Good use of B&W too. The distraction is what appears to be a shadow across the bottom of the shot which is a real shame. = 8', '2007-05-12 12:38:01.000000', NULL, 1),
(3642059, 508286, 78390, '<td valign="top">You can not tell what the food items are, the back splash of the grill seems to the focal point of the photo and distracting, and the sign in the right top corner is blured and distracting from your indented subject.</td>', 'You can not tell what the food items are, the back splash of the grill seems to the focal point of the photo and distracting, and the sign in the right top corner is blured and distracting from your indented subject.', '2007-05-12 14:21:30.000000', NULL, 1),
(3642061, 506292, 78390, '<td valign="top">Out of focus, heads chopped off, colors are bland, too tight of a crop, but does meet challenge. Better luck next time : )</td>', 'Out of focus, heads chopped off, colors are bland, too tight of a crop, but does meet challenge. Better luck next time : )', '2007-05-12 14:22:38.000000', NULL, 1),
(3642066, 506246, 78390, '<td valign="top">This could have been so much better if the colors were more vibrant.</td>', 'This could have been so much better if the colors were more vibrant.', '2007-05-12 14:25:21.000000', NULL, 1),
(3642114, 508287, 69183, '<td valign="top">I like the candid-ness of the shot, but it''s overexposed and the skin tones are a bit orange. On the other hand, the area below the gun is quite dark, so maybe adjusting the contrast/brightness would have produced a more evenly exposed shot.</td>', 'I like the candid-ness of the shot, but it''s overexposed and the skin tones are a bit orange. On the other hand, the area below the gun is quite dark, so maybe adjusting the contrast/brightness would have produced a more evenly exposed shot.', '2007-05-12 15:02:51.000000', NULL, 1),
(3642116, 509276, 69183, '<td valign="top">Nice; you''ve captured his expression perfectly</td>', 'Nice; you''ve captured his expression perfectly', '2007-05-12 15:03:35.000000', NULL, 1),
(3642129, 508204, 69183, '<td valign="top">The three sets of people (two on he left, two centre, one to the right) all seem to be working independently of each other, rather than acting in concert. For me, this results in a disconnected picture with nothing unifying the groups , and that makes it less powerful than it could be - my opinion only, of course. I still like the photo, but I can''t help wondering what it would have looked like half a second before or after.</td>', 'The three sets of people (two on he left, two centre, one to the right) all seem to be working independently of each other, rather than acting in concert. For me, this results in a disconnected picture with nothing unifying the groups , and that makes it less powerful than it could be - my opinion only, of course. I still like the photo, but I can''t help wondering what it would have looked like half a second before or after.', '2007-05-12 15:13:06.000000', NULL, 1),
(3642134, 509053, 69183, '<td valign="top">Cool - bright with good initial appeal. A bit overexposed particularly on the left pillar. South Bank, at a guess?</td>', 'Cool - bright with good initial appeal. A bit overexposed particularly on the left pillar. South Bank, at a guess?', '2007-05-12 15:17:13.000000', NULL, 1),
(3642138, 509176, 69183, '<td valign="top">LOL. I bet you''re gonna get at leat some "huh" and DNMCs, but I like this. 10.</td>', 'LOL. I bet you''re gonna get at leat some "huh" and DNMCs, but I like this. 10.', '2007-05-12 15:21:06.000000', NULL, 1),
